package com.bn.aliagent.evaluation.candidate;
import java.time.*;
public final class CandidateRetentionService { private final CandidateRepository repo;private final Clock clock;public CandidateRetentionService(CandidateRepository r,Clock c){repo=r;clock=c;} public RetentionResult purgeExpired(){int expired=0,redacted=0;for(var v:repo.all().toArray(EvaluationCandidate[]::new)){long days=Duration.between(v.createdAt(),clock.instant()).toDays();if(v.status()==CandidateStatus.PENDING_REVIEW&&days>=30){repo.save(new EvaluationCandidate(v.id(),v.tenantId(),CandidateStatus.EXPIRED,java.util.Optional.empty(),v.digest(),v.createdAt(),v.expected(),v.labels(),v.reason()));expired++;}else if((v.status()==CandidateStatus.REJECTED||v.status()==CandidateStatus.QUARANTINED)&&days>=7&&v.body().isPresent()){repo.save(new EvaluationCandidate(v.id(),v.tenantId(),v.status(),java.util.Optional.empty(),v.digest(),v.createdAt(),v.expected(),v.labels(),v.reason()));redacted++;}}return new RetentionResult(expired,redacted);} public record RetentionResult(int expired,int redacted){} }
